-- Add the fourth supplied set of Lily facts (cards 301–400). This is
-- append-only: earlier cards and their learner delivery history remain intact.
WITH supplied_facts (ordinal, text) AS (
VALUES
  (301, $$Джеймс Макферсон в 1760-х годах взорвал литературный мир Европы, опубликовав переводы древних поэм шотландского барда III века Оссиана. Позже выяснилось, что никакого Оссиана не существовало: Макферсон сам сочинил все стихи, собрав воедино кельтский фольклор.$$),
  (302, $$Ромен Гари — единственный писатель, получивший престижную Гонкуровскую премию дважды (по закону её дают раз в жизни). Первую он взял под своим именем, а вторую — под псевдонимом Эмиль Ажар. Мистификация раскрылась только после смерти автора.$$),
  (303, $$Борис Акунин (Григорий Чхартишвили) параллельно с серией об Эрасте Фандорине тайно выпускал романы под именами Анна Борисова и Анатолий Брусникин, чтобы проверить, будут ли его читать без громкого бренда «Акунин». Проект оказался успешным.$$),
  (304, $$Проспер Мериме в юности издал сборник пьес «Театр Клары Гасуль», выдав себя за неизвестную испанскую актрису, а чуть позже — сборник баллад «Гузла», выдав его за переводы песен южнославянского певца Иакинфа Маглановича. В этот обман искренне поверил даже Александр Пушкин.$$),
  (305, $$Черубина де Габриак — одна из самых ярких мистификаций Серебряного века. Под этим именем скрывалась скромная учительница Елизавета Дмитриева. Стихи «таинственной испанской графини-католички» сводили с ума редакцию журнала «Аполлон» и привели к реальной дуэли между Максимилианом Волошиным и Николаем Гумилевым.$$),
  (306, $$Томас Чаттертон, английский поэт XVIII века, в 16 лет подделал стихи вымышленного средневекового монаха Томаса Роули. Текст был написан на старинном пергаменте самодельными чернилами. Когда обман раскрылся, Чаттертон от нищеты и непризнания покончил с собой в возрасте 17 лет, став иконой для романтиков.$$),
  (307, $$Книга «Оаспе» (1882) — пример так называемого «автоматического письма». Стоматолог Джон Ньюбро утверждает, что его руками управляли высшие ангельские сущности, которые с помощью печатной машинки набрали совершенно новую священную историю человечества.$$),
  (308, $$Майкл Крайтон (автор «Парка Юрского периода»), будучи студентом Гарварда, устал от того, что профессор литературы занижает ему оценки. Он сдал чужое эссе, написанное Джорджем Оруэллом, и профессор поставил этому тексту тройку с минусом, доказав свою предвзятость.$$),
  (309, $$Лоренс Стерн в романе «Жизнь и мнения Тристрама Шенди, джентльмена» (XVIII век) обогнал свое время: он оставил в книге абсолютно черную страницу в знак траура по персонажу, а также пустые страницы, чтобы читатель сам нарисовал портрет возлюбленной героя.$$),
  (310, $$Скандал с дневниками Гитлера (1983 год) — крупнейший обман в истории послевоенной прессы. Журнал Stern купил 62 тома фальшивых дневников у мошенника Конрада Куяу за 9 миллионов марок. Экспертиза по составу бумаги и клея быстро доказала, что это грубая подделка.$$),
  (311, $$Франц Кафка испытывал глубочайший комплекс неполноценности перед своим деспотичным отцом. Его знаменитое 100-страничное «Письмо отцу» — один из самых болезненных психологических документов в истории, который отец писателя так никогда и не прочитал.$$),
  (312, $$Эрнест Хемингуэй в конце жизни страдал от тяжелой паранойи. Ему казалось, что за ним повсюду следят агенты ФБР, прослушивают его телефон и расставляют жучки в психиатрической клинике, где его лечили электрошоком. Спустя десятилетия после его самоубийства документы ФБР были рассекречены — слежка действительно велась.$$),
  (313, $$Оскар Уайльд после двух лет каторжных работ за «непристойное поведение» вышел из тюрьмы совершенно сломленным человеком. Он уехал во Францию, сменил имя на Себастьян Мельмот и доживал свои дни в дешевых гостиницах Парижа, практически нищенствуя.$$),
  (314, $$Артур Конан Дойл на склоне лет стал фанатичным спиритуалистом. Он тратил целые состояния на сеансы вызова духов и искренне верил в подлинность фотографий «фей из Коттингли», которые оказались банальными бумажными фигурками, вырезанными девочками из детской книжки.$$),
  (315, $$Вирджиния Вулф всю жизнь боролась с тяжелыми приступами биполярного расстройства. Во время обострений она слышала голоса птиц, поющих на древнегреческом языке в ее саду.$$),
  (316, $$Стивен Кинг панически боится летать на самолетах. Если ему нужно пересечь США, он предпочитает ехать за рулем своего автомобиля или на поезде, несмотря на колоссальные потери времени.$$),
  (317, $$Ганс Христиан Андерсен страдал от невероятного количества комплексов и фобий. Помимо страха пожаров, он до ужаса боялся быть похороненным заживо, поэтому перед сном всегда оставлял на тумбочке записку: «Я только кажусь мертвым». Также он никогда не позволял лечить свои зубы, веря, что от количества зубов зависит его писательский талант.$$),
  (318, $$Лев Толстой в 1869 году пережил так называемый «Арзамасский ужас» — внезапный приступ дикого, экзистенциального страха смерти и бессмысленности бытия во время ночевки в гостинице Арзамаса. Этот момент полностью перевернул его мировоззрение и разделил творчество на «до» и «после».$$),
  (319, $$Чарльз Диккенс был одержим моргами. Приезжая в любой новый город (особенно в Париж), он первым же делом отправлялся в местный морг и мог часами разглядывать неопознанные тела, утверждая, что его притягивает «тайна ушедших жизней».$$),
  (320, $$Агата Кристи в 1926 году загадочно исчезла на 11 дней после ссоры с мужем, который потребовал развода. Ее искали тысячи добровольцев и полиция по всей Англии. Писательницу нашли в спа-отеле, где она зарегистрировалась под фамилией любовницы своего мужа. Сама Кристи утверждала, что пережила полную амнезию и ничего не помнит.$$),
  (321, $$«Библия прелюбодеев» (Wicked Bible) — издание 1631 года, в котором королевские печатники в Англии допустили катастрофическую опечатку в седьмой заповеди. Текст гласил: «Прелюбодействуй» (слово «не» было случайно пропущено). Почти весь тираж был уничтожен, а типографию оштрафовали на огромную сумму.$$),
  (322, $$«Кодекс Рохонци» — манускрипт неизвестного происхождения, обнаруженный в Венгрии в XIX веке. На 448 страницах содержится текст, написанный уникальным алфавитом из 792 знаков, дополненный религиозными иллюстрациями. Книга до сих пор не расшифрована и считается либо гениальной мистификацией, либо утерянным языком.$$),
  (323, $$Книга из свинца — в 2008 году в Иордании были найдены свинцовые металлические книги (свинцовые кодексы), скрепленные проволокой. На страницах размером с кредитную карту выбиты раннехристианские символы. Вокруг их подлинности до сих пор ведутся ожесточенные научные споры.$$),
  (324, $$Самый дорогой комикс в истории — выпуск Action Comics #1 (первое появление Супермена), который в 2024 году был продан на аукционе за рекордные 6 миллионов долларов.$$),
  (325, $$Книги с секретными картинами на обрезах (Fore-edge painting) — старинная техника оформления, когда на срез страниц наносился рисунок. В закрытом виде книга кажется обычной, но если слегка сдвинуть страницы веером, на торце проявляется детальный пейзаж или портрет.$$),
  (326, $$«Поминки по Финнегану» Джеймса Джойса — книга, написанная на придуманном автором «полиглотском» языке, состоящем из смеси слов десятков европейских языков, каламбуров и неологизмов. Первое предложение книги является продолжением самого последнего предложения, что замыкает роман в бесконечный круг.$$),
  (327, $$Книги в обложке из бетона — немецкий художник Вольф Фостель в 1960-х годах выпустил арт-объект: тираж книги, полностью залитый в бетонные блоки. Прочитать такую книгу, не уничтожив ее, физически невозможно.$$),
  (328, $$Самая большая печатная книга по площади — «Маленький принц», изданная в Бразилии. Ее размеры в раскрытом виде составляют 3,08 метра в ширину и 2,01 метра в высоту.$$),
  (329, $$Миниатюрный «Коран» — в некоторых музеях мира хранятся старинные микроиздания Корана размером менее 2х2 см, которые мусульманские воины носили в специальных металлических медальонах-амулетах на шее.$$),
  (330, $$Книга, которая пожирает сама себя — португальское издательство в рамках рекламной кампании выпустило роман на специальной бумаге с чернилами, которые при контакте с воздухом и светом полностью исчезают через 2 месяца после открытия коробки. Это стимулировало покупателей не откладывать чтение.$$),
  (331, $$Жанр любовного романа (Romance) — абсолютный лидер по продажам в сегменте художественной литературы во всем мире. Он приносит издательской индустрии США более 1,4 миллиарда долларов ежегодно.$$),
  (332, $$Самый успешный независимый автор современности — Колин Гувер. Она стала феноменом благодаря продвижению своих книг в сообществе BookTok (в TikTok), что позволило ей обогнать по продажам Библию в определенные месяцы.$$),
  (333, $$Исландия — самая читающая страна в мире на душу населения. Здесь существует древняя традиция Jolabokaflod («Рождественский книжный потоп»), когда в сочельник абсолютно все дарят друг другу книги и проводят ночь за чтением.$$),
  (334, $$Первый в истории электронный текст создал Майкл Харт в 1971 году, когда ввел Декларацию независимости США в компьютер в университете Иллинойса. Так родился знаменитый проект бесплатной электронной библиотеки «Гутенберг».$$),
  (335, $$США и Китай делят первые места по объёму книжного рынка в мире, однако по количеству публикуемых новых наименований книг в год Китай уверенно лидирует (более 440 тысяч книг ежегодно).$$),
  (336, $$Среднестатистический человек за всю свою жизнь физически способен прочитать от 3 000 до 6 000 книг, если будет читать по одной книге в неделю с подросткового возраста до старости. Это ничтожно мало по сравнению с миллионами существующих томов.$$),
  (337, $$Аудиокниги — самый быстрорастущий сектор книжного рынка. Согласно статистике, большинство людей слушают аудиокниги во время работы по дому, за рулем или во время занятий спортом.$$),
  (338, $$Самая длинная подписка на журнал в истории принадлежит англичанину, который выписывал журнал The Spectator на протяжении 74 лет подряд.$$),
  (339, $$Книжный пиратский сайт Library Genesis (LibGen) содержит более 3 миллионов электронных книг и десятки миллионов научных статей, являясь крупнейшей теневой цифровой библиотекой в истории Земли.$$),
  (340, $$Полки в магазинах IKEA — знаменитый стеллаж «БИЛЛИ» (BILLY) является самым продаваемым элементом мебели компании. Каждые 5 секунд где-то в мире продается один такой книжный стеллаж.$$),
  (341, $$Роман «Страдания молодого Вертера» Гёте (1774) вызвал первую в истории задокументированную волну подражательных самоубийств среди молодежи в Европе. Юноши одевались в желтые жилеты и синие фраки ( как Вертер) и стрелялись. Книгу пришлось запретить в нескольких странах. Отсюда пошел психологический термин «Эффект Вертера».$$),
  (342, $$«Крестный отец» Марио Пьюзо кардинально изменил реальную мафию. До выхода книги и фильма американские гангстеры не использовали в обиходе такие термины, как «Коза Ностра» или «сделать предложение, от которого нельзя отказаться», и не включали классическую музыку на встречах — они начали копировать поведение героев Брандо и Пачино, чтобы казаться более солидными.$$),
  (343, $$Образ Санта-Клауса в красно-белой шубе и на оленьей упряжке был окончательно сформирован благодаря стихотворению Клемента Мура «Визит святого Николая» (1823). До этого Николай изображался в строгих епископских одеждах или даже как худой эльф.$$),
  (344, $$Роман «Двадцать тысяч лье под водой» Жюля Верна вдохновил американского инженера Саймона Левика на создание первой в мире функциональной подводной лодки «Аргонавт». Левик лично написал Верну письмо с благодарностью.$$),
  (345, $$После выхода романа «Парфюмер» Патрика Зюскинда в мировой индустрии парфюмерии вырос спрос на моноароматы и редкие анималистические эссенции, а сама книга стала настольной для многих современных создателей нишевых духов.$$),
  (346, $$«1984» Джорджа Оруэлла подарила миру термины: «мыслепреступление», «двоемыслие», «новояз» и «новость-новодел», которые сегодня официально используются политологами и социологами для описания методов государственной пропаганды.$$),
  (347, $$Барон Мюнхгаузен — абсолютно реальный человек (Иероним Карл Фридрих фон Мюнхгаузен), который служил в русской армии и любил рассказывать байки на охоте. Писатель Рудольф Эрих Распе без разрешения взял его истории, переработал их и издал книгу, превратив имя барона в нарицательное, из-за чего реальный Мюнхгаузен долго судился и умер в обиде на весь мир.$$),
  (348, $$«Иллюминаты» стали мейнстримной темой теории заговора благодаря фантастической трилогии Роберта Ши и Роберта Антона Уилсона «Иллюминатус!» (1975). Авторы изначально задумывали книгу как сатиру на паранойю американского общества, но читатели восприняли всё всерьез.$$),
  (349, $$После выхода фильма и серии книг «Челюсти» Питера Бенчли в мире началась массовая истерия и истребление белых акул. Писатель позже настолько раскаялся в том, что демонизировал этих рыб, что посвятил остаток жизни защите океанской фауны.$$),
  (350, $$«Зона» и «Сталкер» — братья Стругацкие в повести «Пикник на обочине» (1972) придумали концепт аномальной Зоны, охраняемой военными, и проводников-сталкеров. Спустя 14 лет произошла авария на Чернобыльской АЭС, создавшая реальную Чернобыльскую зону отчуждения, ликвидаторов и посетителей которой моментально начали называть сталкерами.$$),
  (351, $$Слово «Chortle» (смешок, хохот) было выдумано Льюисом Кэрроллом в его знаменитом абсурдном стихотворении «Бармаглот» путем скрещивания слов chuckle (похихикивать) и snort (фыркать). Сегодня это официальное английское слово.$$),
  (352, $$Имя Светлана не является древнеславянским. Его придумал и впервые использовал поэт Александр Востоков в романсе «Светлана и Мстислав» (1802), а культовую популярность оно обрело после публикации одноименной баллады Василия Жуковского.$$),
  (353, $$Слово «Мазохизм» было введено в психиатрию немецким неврологом Рихардом фон Крафт-Эбингом. Он назвал это явление в честь писателя Леопольда фон Захер-Мазоха, который детально описывал подобные сексуальные и психологические девиации в своих романах (самый известный — «Венера в мехах»).$$),
  (354, $$Имя Гаргантюа происходит от португальского корня, означающего «глотка». Франсуа Рабле превратил его в имя великана-обжоры, сделав слово «гаргантюанский» синонимом чего-то невероятно огромного.$$),
  (355, $$Слово «Галиматья» имеет литературный след. В средние века во Франции судились из-за петуха, принадлежавшего человеку по имени Матиас. Адвокат, выступая на латыни, запутался и вместо Gallus Mathiae (петух Матиаса) постоянно говорил Galli Mathias (петушиный Матиас). Эта бессмысленная речь стала синонимом чепухи.$$),
  (356, $$Слово «Панорама» было придумано и запатентовано ирландским художником Робертом Баркером в 1787 году для описания его круговых картин, а писатели быстро подхватили его для описания широкого обзора в текстах.$$),
  (357, $$Имя Фиона было выдумано шотландским поэтом Уильямом Шарпом, который писал романтические стихи под женским псевдонимом Фиона Маклеод.$$),
  (358, $$Слово «Мальчиш-Плохиш» из сказки Аркадия Гайдара стало в русском языке абсолютным синонимом предателя, продавшегося за материальные блага («банку варенья и корзину печенья»).$$),
  (359, $$Слово «Дредноут» (вид боевого корабля) переводится с английского буквально как «бесстрашный», но в литературу этот концепт ввели поэты-романтики, описывавшие несгибаемый дух моряков.$$),
  (360, $$Слово «Недоросль» до комедии Дениса Фонвизина было официальным юридическим термином в Российской империи — так называли молодых дворян, не получивших письменного удостоверения об образовании, которых из-за этого не принимали на службу. Фонвизин превратил это слово в клеймо для глупых и ленивых маменькиных сынков.$$),
  (361, $$Федор Достоевский страдал тяжелой формой эпилепсии. Он часто использовал свои личные ощущения от припадков при описании состояний персонажей (например, князя Мышкина в «Идиоте» или Кириллова в «Бесах»).$$),
  (362, $$Александр Блок умер в 1921 году от воспаления сердечных клапанов, вызванного хроническим недоеданием и глубочайшей депрессией. Перед смертью поэт в бреду требовал уничтожить все до единого экземпляры его знаменитой поэмы «Двенадцать».$$),
  (363, $$Иван Бунин был невероятно мнительным человеком и панически боялся змей. Перед сном он тщательно осматривал свою постель, а в путешествиях по Азии требовал от прислуги проверять каждый угол номера.$$),
  (364, $$Анна Ахматова (Анна Горенко) взяла свой псевдоним после того, как отец, узнав о ее поэтических опытах, заявил: «Не позорь мое имя». Она выбрала фамилию своей прабабки, которая, по легенде, вела свой род от татарского хана Ахмата.$$),
  (365, $$Николай Гумилев во время Первой мировой войны добровольно пошел на фронт простым уланом. За проявленное мужество, дерзкие разведки и спасение пулемета он был дважды награжден Георгиевским крестом — высшей солдатской наградой империи.$$),
  (366, $$Корней Чуковский терпеть не мог, когда его ассоциировали исключительно с «Мухой-Цокотухой» и «Мойдодыром». Он считал своим главным жизненным трудом фундаментальные переводы и исследования творчества Николая Некрасова и Уолта Уитмена.$$),
  (367, $$Сергей Есенин и Владимир Маяковский устраивали на публичных поэтических батлах жесткие словесные дуэли, обзывая друг друга «деревенщиной» и «ремесленником», однако в частных беседах оба признавали колоссальный талант друг друга.$$),
  (368, $$Осип Мандельштам был арестован и отправлен в ссылку за одно единственное стихотворение — «Мы живем, под собою не чуя страны...», в котором он назвал Сталина «кремлевским горцем» с «тараканьими усищами». Стихотворение не было записано, кто-то из слушателей донес на поэта по памяти.$$),
  (369, $$Михаил Зощенко в конце жизни подвергся жесточайшей травле со стороны советских властей (знаменитое постановление Жданова 1946 года). Его исключили из Союза писателей, лишили средств к существованию, и великий сатирик был вынужден подрабатывать сапожным ремеслом, переводя обувь на дому.$$),
  (370, $$Борис Пастернак под давлением советского правительства и угрозы высылки из страны был вынужден отказаться от уже присужденной ему Нобелевской премии по литературе за роман «Доктор Живаго». Награду вместо него спустя годы получил его сын.$$),
  (371, $$Айзек Азимов страдал от жуткой агорафобии (боязни открытых пространств) и клаустрофилии (любви к замкнутым помещениям). Он предпочитал работать в маленьких кабинетах без окон, включив искусственный свет. Именно эта его особенность легла в основу описания подземных городов планеты Трантор в цикле «Основание».$$),
  (372, $$Джин Родденберри (создатель «Звездного пути», написавший массу новеллизаций) стал одним из первых людей в истории, чей прах после смерти был отправлен в космос на борту ракеты Pegasus и развеян на орбите Земли.$$),
  (373, $$Роман «Мечтают ли андроиды об электроовцах?» Филипа Дика был адаптирован Ридли Скоттом под названием «Бегущий по лезвию». Филип Дик успел увидеть лишь несколько минут рабочих материалов фильма перед своей смертью и был поражен тем, как точно Рутгер Хауэр и Харрисон Форд передали атмосферу его книги.$$),
  (374, $$Герберт Уэллс в романе «Война миров» (1898) впервые в истории описал концепт лазерного оружия (Тепловой луч марсиан) и боевых шагающих роботов (Треножники).$$),
  (375, $$Терри Пратчетт при создании Плоского мира опирался на древние индуистские и скандинавские мифы, где Земля действительно покоится на спинах четырех слонов, которые стоят на гигантской черепахе Великий Атуин.$$),
  (376, $$Стивен Кинг написал свой монументальный цикл «Темная Башня» под впечатлением от поэмы Роберта Браунинга «Чайльд-Роланд к Темной Башне пришел», а образ стрелка Роланда списан с героя Клинта Иствуда в вестернах Серджио Леоне.$$),
  (377, $$Фрэнк Герберт закладывал в «Дюну» глубокий экологический и религиозный подтекст. Образ спайса (пряности), за которую воюет вся вселенная, является прямой метафорой на нефть Ближнего Востока, а фремены списаны с кочевых бедуинов.$$),
  (378, $$Джордж Мартин изначально планировал написать «Песнь Льда и Пламени» как трилогию. Однако мир разросся настолько, что превратился в масштабную сагу, финал которой фанаты ждут годами.$$),
  (379, $$Киберпанк как термин был придуман не Уильямом Гибсоном, а писателем Брюсом Бетке, который в 1980 году опубликовал рассказ с названием «Киберпанк». Гибсон лишь развил и зацементировал этот стиль.$$),
  (380, $$Дуглас Адамс был страстным защитником окружающей среды. Ради спасения редких видов носорогов он однажды совершил восхождение на гору Килиманджаро в массивном ростовом костюме носорога.$$),
  (381, $$«Синайский кодекс» (Codex Sinaiticus) — рукопись Библии IV века, написанная на пергаменте на древнегреческом языке. Она была случайно обнаружена немецким ученым Константином Тишендорфом в куче мусора в монастыре Святой Екатерины, которую монахи собирались использовать для растопки печей.$$),
  (382, $$Свиток Рипли — алхимическая рукопись XV века длиной около 6 метров, содержащая зашифрованные в виде загадочных картинок рецепты создания Философского камня и эликсира бессмертия.$$),
  (383, $$«Золотые листы из Пирги» — три золотые пластины конца VI века до н.э., найденные в Италии. Текст на них выбит на двух языках: этрусском и финикийском. Благодаря этому артефакту ученые смогли продвинуться в расшифровке таинственного этрусского языка.$$),
  (384, $$Папирус Весткар — древнеегипетский манускрипт, содержащий пять сказок о чудесах и магах, которые рассказывают сыновья фараона Хуфу (Хеопса) своему отцу. Это старейший сборник сказок в истории человечества.$$),
  (385, $$Эффект сгорания свитков Геркуланума — во время извержения Везувия в 79 году н.э. целая библиотека виллы в Геркулануме превратилась в обугленные головешки. В XXI веке ученые научились читать эти свитки, не разворачивая их, с помощью компьютерной томографии и искусственного интеллекта, распознающего плотность чернил на сожженном папирусе.$$),
  (386, $$«Черная книга монарха» — старинное название судебных книг средневековой Англии, куда заносились самые тяжкие преступления против короны, включая колдовство и государственную измену.$$),
  (387, $$Манускрипт Аль-Азиф — вымышленная книга, придуманная Говардом Лавкрафтом (более известная как Некрономикон). Лавкрафт так детально описал ее историю, авторов и переводы, что миллионы людей до сих пор пытаются найти ее в реальных библиотеках.$$),
  (388, $$«Книга Коров» — древнеегипетский священный текст, высеченный на стенах гробниц Тутанхамона и Сети I. В нем описывается миф о том, как человечество восстало против бога Ра, и как он решил наказать людей, послав на землю яростную богиню Сехмет в образе львицы.$$),
  (389, $$Саксонская хроника — древнейшая летопись Англии, охватывающая период с V века до 1154 года. Это главный источник информации о временах короля Артура и набегах викингов.$$),
  (390, $$«Кодекс Борджиа» — мезоамериканская рукопись из кожи оленя, созданная до испанского завоевания Мексики. Книга содержит сложнейшие ритуальные календари ацтеков и пророчества, написанные пиктографическим письмом.$$),
  (391, $$Джордж Мартин пишет свои романы исключительно в полной тишине. У него есть два дома на одной улице: в одном он живет с женой, а во второй уходит каждое утро как в офис, чтобы писать книги, не отвлекаясь на бытовой шум.$$),
  (392, $$Стивен Кинг панически боится «творческого застоя», поэтому установил для себя жесткое правило: писать не менее 2000 слов каждый день без исключений на праздники, выходные или болезни.$$),
  (393, $$Дж. К. Роулинг призналась, что ее любимый персонаж в «Гарри Поттере» — Альбус Дамблдор. Она заявила, что если бы ей пришлось провести вечер в разговорах с кем-то из своих героев, это был бы исключительно директор Хогвартса.$$),
  (394, $$Дэн Браун при написании «Ангелов и Демонов» лично провел несколько недель в архивах Ватикана и прошел весь «Путь Просвещения» по римским церквям, чтобы с точностью до метра выверить хронометраж перемещений профессора Лэнгдона.$$),
  (395, $$Нил Гейман коллекционирует старинные чернильницы и перьевые ручки. Он утверждает, что у каждого его романа есть своя «выделенная ручка», которой написан первый черновик текста.$$),
  (396, $$Энди Уир написал свой хит «Марсианин», будучи обычным программистом. Он выкладывал главы бесплатно в своем блоге, а детальные научные расчеты траекторий кораблей и выживания на Марсе делал с помощью собственноручно написанных программ.$$),
  (397, $$Ли Чайлд (автор серии о Джеке Ричере) взял свой псевдоним из-за шутки: его дочь неправильно расслышала название автомобиля Renault Le Car как «Lee Car». Писатель решил, что «Ли» — отличное короткое имя для обложки.$$),
  (398, $$Сьюзен Коллинз долгое время работала сценаристом детских телешоу на канале Nickelodeon, включая знаменитый сериал «Вау! Вау! Ваббзи!», до того как переключиться на жестокие антиутопии.$$),
  (399, $$Харуки Мураками ведет строжайший спортивный образ жизни: он ежедневно пробегает по 10 километров или проплывает 1500 метров, ложится спать в 21:00 и встает в 4:00 утра. Писатель утверждает, что без мощной физической подготовки невозможно выдерживать многочасовую писательскую концентрацию.$$),
  (400, $$Томас Харрис никогда не смотрел фильм «Молчание ягнят» с Энтони Хопкинсом и Джоди Фостер. Писатель боится, что гениальные актерские образы подменят в его голове тех персонажей, которых он создал на бумаге, и помешают ему писать продолжение.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  CASE WHEN ordinal BETWEEN 351 AND 360 THEN 'PHILOLOGY' ELSE 'LITERATURE' END,
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;
